def match(orders):
    import heapq

    buy_heap = []   # entries: (-price, arrival, id)
    sell_heap = []  # entries: (price, arrival, id)
    book = {}       # id -> {'side','price','qty','arrival'}
    trades = []

    for arrival, o in enumerate(orders):
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            _, oid, side, price, qty = o

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            opp_id = top[2]

            if opp_id not in book:
                heapq.heappop(opp_heap)
                continue

            opp_order = book[opp_id]

            # sanity check: order might have stale entry with different qty but that's fine,
            # since qty is updated in place in book, and heap only used to determine order.
            # price condition check (skip for market orders)
            if typ != 'market':
                if side == 'buy' and opp_order['price'] > price:
                    break
                if side == 'sell' and opp_order['price'] < price:
                    break

            trade_qty = min(remaining, opp_order['qty'])
            trade_price = opp_order['price']

            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            opp_order['qty'] -= trade_qty

            if opp_order['qty'] == 0:
                heapq.heappop(opp_heap)
                del book[opp_id]
            # else partially filled resting order keeps its place; stays in heap and book

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'arrival': arrival}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival, oid))
        # ioc/market leftover qty discarded; fully filled limit orders don't rest

    return trades

